const v = $input.first().json;

const splitList = (value) => (Array.isArray(value) ? value : String(value || '').split(/[,;\n]/))
  .map((part) => String(part).trim())
  .filter(Boolean);

const sector = String(v.sector || '').trim();
const zona = String(v.zona || '').trim();
const carrecs = splitList(v.carrecs_objectiu);
const paraules = splitList(v.paraules_clau);
const limit = Math.max(1, Math.min(100, Math.floor(Number(v.limit_resultats) || 25)));
let actorId = String(v.apify_actor_id || '').trim().replace('/', '~');
let sheetId = String(v.google_sheet_id || '').trim();
const sheetUrlMatch = sheetId.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);
if (sheetUrlMatch) sheetId = sheetUrlMatch[1];

if (!sector) throw new Error('Falta el sector.');
if (!zona) throw new Error('Falta la zona/geografia.');
if (!carrecs.length) throw new Error('Falta com a mínim un càrrec objectiu.');
if (!actorId || actorId === 'APIFY_ACTOR_ID') throw new Error('Substitueix APIFY_ACTOR_ID. Recomanat: harvestapi~linkedin-profile-search');
if (!sheetId || sheetId === 'GOOGLE_SHEET_ID') throw new Error('Substitueix GOOGLE_SHEET_ID per un identificador o URL del full.');

return [{
  json: {
    sector,
    zona,
    carrecs_objectiu: carrecs,
    paraules_clau: paraules,
    limit_resultats: limit,
    apify_actor_id: actorId,
    google_sheet_id: sheetId,
    google_sheet_tab: String(v.google_sheet_tab || 'Leads').trim() || 'Leads',
    openai_model: String(v.openai_model || 'gpt-5-mini').trim(),
    search_query: [sector, ...paraules].filter(Boolean).join(' '),
    data_captura: new Date().toISOString()
  }
}];

const payload = $input.first().json;
const config = $('Validar input').first().json;
let rawItems = payload.body ?? payload;
if (typeof rawItems === 'string') {
  try { rawItems = JSON.parse(rawItems); } catch { rawItems = []; }
}
if (!Array.isArray(rawItems)) rawItems = Array.isArray(rawItems.items) ? rawItems.items : [];

const cleanText = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value).trim();
  if (Array.isArray(value)) return cleanText(value[0]);
  return cleanText(value.linkedinText ?? value.text ?? value.name ?? value.title ?? value.value ?? '');
};
const normalize = (value) => cleanText(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
const canonicalUrl = (value) => {
  const url = cleanText(value).split('?')[0].replace(/\/$/, '');
  return url ? url.replace(/^http:/i, 'https:') : '';
};
const hash53 = (text, seed = 0) => {
  let h1 = 0xdeadbeef ^ seed;
  let h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < text.length; i++) {
    const ch = text.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36).toUpperCase();
};

const seenUrls = new Set();
const seenPeople = new Set();
const output = [];

for (const raw of rawItems) {
  if (!raw || typeof raw !== 'object' || raw.error) continue;
  const first = cleanText(raw.firstName);
  const lastRaw = cleanText(raw.lastName);
  const last = normalize(lastRaw) === 'undefined' ? '' : lastRaw;
  const name = cleanText(raw.fullName ?? raw.name) || [first, last].filter(Boolean).join(' ');
  const url = canonicalUrl(raw.linkedinUrl ?? raw.profileUrl ?? raw.profileURL ?? raw.url ?? raw.profile?.linkedinUrl);
  if (!name || !url) continue;

  const current = Array.isArray(raw.currentPosition) ? (raw.currentPosition[0] || {}) : (raw.currentPosition || {});
  const experience = Array.isArray(raw.experience)
    ? (raw.experience.find((entry) => !entry?.endDate || /present|actualitat|actual/i.test(cleanText(entry.endDate))) || raw.experience[0] || {})
    : {};
  const position = cleanText(raw.jobTitle ?? raw.currentJobTitle ?? raw.title ?? raw.position ?? current.position ?? current.title ?? experience.position ?? raw.headline);
  let company = cleanText(raw.companyName ?? raw.company ?? current.companyName ?? current.company?.name ?? experience.companyName);
  if (!company && position) {
    const match = position.match(/\s(?:at|@)\s([^|•]+?)(?:\s[|•]|$)/i);
    if (match) company = match[1].trim();
  }
  const location = cleanText(raw.location ?? raw.geoLocation ?? raw.addressWithCountry ?? raw.city);
  const headline = cleanText(raw.headline ?? raw.position ?? raw.summary ?? raw.about).slice(0, 1000);

  const urlKey = normalize(url);
  const personKey = `${normalize(name)}|${normalize(company)}`;
  if (seenUrls.has(urlKey) || (company && seenPeople.has(personKey))) continue;
  seenUrls.add(urlKey);
  if (company) seenPeople.add(personKey);

  const stableKey = urlKey || personKey;
  output.push({ json: {
    'ID': `LEAD-${hash53(stableKey)}`,
    'Data captura': config.data_captura,
    'Sector': config.sector,
    'Zona': config.zona,
    'Nom': name,
    'Càrrec': position,
    'Empresa': company,
    'URL LinkedIn': url,
    'Ubicació': location,
    'Headline': headline,
    'Estat lead': '',
    'Missatge LinkedIn suggerit': '',
    'Notes': '',
    'Font': `Apify: ${config.apify_actor_id}`,
    'Duplicat?': 'No',
    'Última actualització': config.data_captura
  }});
}

return output;

const limitMessage = (value) => {
  let text = String(value || '').replace(/^[\s\"'“”]+|[\s\"'“”]+$/g, '').replace(/\s+/g, ' ').trim();
  const chars = Array.from(text);
  if (chars.length <= 300) return text;
  const shortened = chars.slice(0, 299).join('');
  const cut = shortened.lastIndexOf(' ');
  return `${shortened.slice(0, cut > 240 ? cut : 299).trim()}…`;
};

return $input.all().map((item) => {
  const j = item.json;
  let generated = '';
  if (Array.isArray(j.output)) {
    for (const block of j.output) {
      for (const content of (block.content || [])) {
        if (content.type === 'output_text' && content.text) generated += content.text;
      }
    }
  }
  generated = generated || j.output_text || '';
  const firstName = String(j['Nom'] || '').split(/\s+/)[0] || 'hola';
  const companyPart = j['Empresa'] ? ` a ${j['Empresa']}` : '';
  const fallback = `Hola ${firstName}, he vist el teu rol${companyPart}. A AImetos ajudem empreses a automatitzar processos repetitius amb agents IA per estalviar temps i no perdre oportunitats. Té sentit parlar-ne?`;
  const message = limitMessage(generated || fallback);

  return { json: {
    'ID': j['ID'],
    'Data captura': j['Data captura'],
    'Sector': j['Sector'],
    'Zona': j['Zona'],
    'Nom': j['Nom'],
    'Càrrec': j['Càrrec'],
    'Empresa': j['Empresa'],
    'URL LinkedIn': j['URL LinkedIn'],
    'Ubicació': j['Ubicació'],
    'Headline': j['Headline'],
    'Estat lead': j['Estat lead'] || '',
    'Missatge LinkedIn suggerit': message,
    'Notes': j['Notes'] || '',
    'Font': j['Font'],
    'Duplicat?': j['Duplicat?'],
    'Última actualització': new Date().toISOString()
  }};
});

const config = $('Validar input').first().json;
const leads = $('Preparar registre final').all();
const run = $('Executar actor Apify').first().json.data || {};
return [{ json: {
  estat: 'MVP completat',
  perfils_deduplicats: leads.length,
  sector: config.sector,
  zona: config.zona,
  carrecs_objectiu: config.carrecs_objectiu,
  apify_run_id: run.id || '',
  google_sheet: `https://docs.google.com/spreadsheets/d/${config.google_sheet_id}/edit`,
  avis: 'Revisa manualment cada lead i missatge abans de contactar. Aquest workflow no envia missatges a LinkedIn.'
}}];
